/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_alert_severity_upd` BEFORE UPDATE ON `proximityalert` FOR EACH ROW BEGIN
  IF NEW.miss_distance_km <> OLD.miss_distance_km THEN
    SET NEW.severity = CASE WHEN NEW.miss_distance_km < 1 THEN 'CRITICAL'
                            WHEN NEW.miss_distance_km < 3 THEN 'HIGH'
                            WHEN NEW.miss_distance_km < 6 THEN 'MODERATE'
                            ELSE 'LOW' END;
  END IF;
END */;;
