/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_alert_status_log` AFTER UPDATE ON `proximityalert` FOR EACH ROW BEGIN
  IF NEW.status <> OLD.status THEN
    INSERT INTO AlertStatusHistory (alert_id, old_status, new_status, analyst_id, note)
    VALUES (NEW.alert_id, OLD.status, NEW.status, @current_analyst, @status_note);
  END IF;
END */;;
