--
-- Table structure for table `spaceobject`
--

DROP TABLE IF EXISTS `spaceobject`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `spaceobject` (
  `object_id` int NOT NULL AUTO_INCREMENT,
  `norad_cat_id` int NOT NULL,
  `object_name` varchar(100) NOT NULL,
  `intl_designator` varchar(20) DEFAULT NULL,
  `object_type` enum('PAY','R/B','DEB','UNK') NOT NULL,
  `status_code` varchar(5) DEFAULT NULL,
  `owner_code` varchar(10) DEFAULT NULL,
  `launch_id` int DEFAULT NULL,
  `zone_id` int DEFAULT NULL,
  `orbit_type` varchar(10) DEFAULT NULL,
  `inclination` decimal(6,3) DEFAULT NULL,
  `period_min` decimal(12,3) DEFAULT NULL,
  `apogee_km` decimal(15,3) DEFAULT NULL,
  `perigee_km` decimal(15,3) DEFAULT NULL,
  `rcs_m2` decimal(10,4) DEFAULT NULL,
  `decay_date` date DEFAULT NULL,
  `last_updated` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int DEFAULT NULL,
  PRIMARY KEY (`object_id`),
  UNIQUE KEY `norad_cat_id` (`norad_cat_id`),
  KEY `status_code` (`status_code`),
  KEY `owner_code` (`owner_code`),
  KEY `launch_id` (`launch_id`),
  KEY `updated_by` (`updated_by`),
  KEY `idx_obj_zone_type` (`zone_id`,`object_type`),
  KEY `idx_obj_name` (`object_name`),
  KEY `idx_obj_decay` (`decay_date`),
  CONSTRAINT `spaceobject_ibfk_1` FOREIGN KEY (`status_code`) REFERENCES `opsstatus` (`status_code`),
  CONSTRAINT `spaceobject_ibfk_2` FOREIGN KEY (`owner_code`) REFERENCES `owner` (`owner_code`),
  CONSTRAINT `spaceobject_ibfk_3` FOREIGN KEY (`launch_id`) REFERENCES `launch` (`launch_id`),
  CONSTRAINT `spaceobject_ibfk_4` FOREIGN KEY (`zone_id`) REFERENCES `orbitalzone` (`zone_id`),
  CONSTRAINT `spaceobject_ibfk_5` FOREIGN KEY (`updated_by`) REFERENCES `analyst` (`analyst_id`),
  CONSTRAINT `spaceobject_chk_1` CHECK (((`inclination` is null) or (`inclination` between 0 and 180)))
) ENGINE=InnoDB AUTO_INCREMENT=131072 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

