/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_object_zone_ins` BEFORE INSERT ON `spaceobject` FOR EACH ROW BEGIN
  IF NEW.zone_id IS NULL AND NEW.decay_date IS NULL
     AND NEW.apogee_km IS NOT NULL AND NEW.perigee_km IS NOT NULL THEN
    SET NEW.zone_id = (SELECT zone_id FROM OrbitalZone
                       WHERE (NEW.apogee_km + NEW.perigee_km) / 2 >= altitude_min_km
                         AND (NEW.apogee_km + NEW.perigee_km) / 2 <  altitude_max_km
                       LIMIT 1);
  END IF;
END */;;
DELIMITER ;
