/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_debris_detail_ins` AFTER INSERT ON `spaceobject` FOR EACH ROW BEGIN
  IF NEW.object_type = 'DEB' THEN
    INSERT INTO DebrisDetail (object_id, size_category, event_id)
    VALUES (NEW.object_id,
            CASE WHEN NEW.rcs_m2 IS NULL THEN NULL
                 WHEN NEW.rcs_m2 < 0.1   THEN 'SMALL'
                 WHEN NEW.rcs_m2 <= 1    THEN 'MEDIUM'
                 ELSE 'LARGE' END,
            (SELECT event_id FROM FragmentationEvent
             WHERE NEW.object_name LIKE CONCAT(name_pattern, '%') LIMIT 1));
  END IF;
END */;;
DELIMITER ;
