/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_object_zone_upd` BEFORE UPDATE ON `spaceobject` FOR EACH ROW BEGIN
  IF NEW.decay_date IS NOT NULL THEN
    SET NEW.zone_id = NULL;
  ELSEIF NOT (NEW.apogee_km <=> OLD.apogee_km) OR NOT (NEW.perigee_km <=> OLD.perigee_km) THEN
    SET NEW.zone_id = (SELECT zone_id FROM OrbitalZone
                       WHERE (NEW.apogee_km + NEW.perigee_km) / 2 >= altitude_min_km
                         AND (NEW.apogee_km + NEW.perigee_km) / 2 <  altitude_max_km
                       LIMIT 1);
  END IF;
END */;;
DELIMITER ;
