/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_object_decay` AFTER UPDATE ON `spaceobject` FOR EACH ROW BEGIN
  IF OLD.decay_date IS NULL AND NEW.decay_date IS NOT NULL THEN
    SET @current_analyst = NULL;
    SET @status_note = 'Object decayed, alert closed automatically';
    UPDATE ProximityAlert
       SET status = 'CLOSED'
     WHERE (primary_object_id = NEW.object_id OR secondary_object_id = NEW.object_id)
       AND status IN ('OPEN','ACKNOWLEDGED');
  END IF;
END */;;
DELIMITER ;
