CREATE DEFINER=`root`@`localhost` PROCEDURE `resolve_alert`(
  IN p_alert_id INT, IN p_analyst_id INT,
  IN p_new_status VARCHAR(20), IN p_note VARCHAR(255))
BEGIN
  DECLARE v_old VARCHAR(20);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;
  SELECT status INTO v_old FROM ProximityAlert WHERE alert_id = p_alert_id FOR UPDATE;

  IF v_old IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Alert not found';
  END IF;

  IF NOT ( (v_old = 'OPEN'         AND p_new_status IN ('ACKNOWLEDGED','RESOLVED'))
        OR (v_old = 'ACKNOWLEDGED' AND p_new_status = 'RESOLVED')
        OR (v_old = 'RESOLVED'     AND p_new_status = 'CLOSED') ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Invalid status change';
  END IF;

  SET @current_analyst = p_analyst_id;
  SET @status_note = p_note;
  UPDATE ProximityAlert SET status = p_new_status WHERE alert_id = p_alert_id;
  COMMIT;
END ;;
DELIMITER ;
